import React, { useState } from "react";
import FullCalendar from "@fullcalendar/react"; // Main FullCalendar component
import dayGridPlugin from "@fullcalendar/daygrid";
import { Paper, Stack } from "@mui/material";
import { formatDate } from "@fullcalendar/core";
import { INITIAL_EVENTS, createEventId } from "./event-utils";
import timeGridPlugin from "@fullcalendar/timegrid";
import interactionPlugin from "@fullcalendar/interaction";
import "./calender.css";

function renderEventContent(eventInfo) {
  return (
    <>
      <b>{eventInfo.timeText}</b>
      <i>{eventInfo.event.title}</i>
    </>
  );
}

function renderSidebarEvent(event) {
  return (
    <li key={event.id}>
      <b>
        {formatDate(event.start, {
          year: "numeric",
          month: "short",
          day: "numeric",
        })}
      </b>
      <i>{event.title}</i>
    </li>
  );
}

export default function Calender() {
  const [weekendsVisible, setWeekendsVisible] = useState(true);
  const [currentEvents, setCurrentEvents] = useState([]);
  let eventGuid = 0;

  function createEventId() {
    return String(eventGuid++);
  }

  const handleWeekendsToggle = () => {
    setWeekendsVisible(!weekendsVisible);
  };

  const handleDateSelect = (selectInfo) => {
    let title = prompt("Please enter a new title for your event");
    let calendarApi = selectInfo.view.calendar;

    calendarApi.unselect(); // clear date selection

    if (title) {
      calendarApi.addEvent({
        id: createEventId(),
        title,
        start: selectInfo.startStr,
        end: selectInfo.endStr,
        allDay: selectInfo.allDay,
      });
    }
  };

  const handleEventClick = (clickInfo) => {
    // Use confirm here to ask the user for confirmation before deleting the event
    const isConfirmed = window.confirm(
      `Are you sure you want to delete the event '${clickInfo.event.title}'?`
    );

    if (isConfirmed) {
      clickInfo.event.remove(); // Remove event if confirmed
    }
  };

  const handleEvents = (events) => {
    setCurrentEvents(events);
  };

  return (
    <Stack direction="row">
      <Paper className="demo-app-sidebar">
        <h2 style={{ textAlign: "center", marginTop: "3px" }}>
          All Events ({currentEvents.length})
        </h2>
        <ul style={{ textAlign: "center", marginTop: "3px" }}>
          {currentEvents.map(renderSidebarEvent)}
        </ul>
      </Paper>
      <div className="demo-app-main">
        <FullCalendar
          plugins={[dayGridPlugin, timeGridPlugin, interactionPlugin]}
          headerToolbar={{
            left: "prev,next today",
            center: "title",
            right: "dayGridMonth,timeGridWeek,timeGridDay",
          }}
          initialView="dayGridMonth"
          editable={true}
          selectable={true}
          selectMirror={true}
          dayMaxEvents={true}
          weekends={weekendsVisible}
          initialEvents={INITIAL_EVENTS} // alternatively, use the `events` setting to fetch from a feed
          select={handleDateSelect}
          eventContent={renderEventContent} // custom render function
          eventClick={handleEventClick} // updated to use the confirm dialog
          eventsSet={handleEvents} // called after events are initialized/added/changed/removed
        />
      </div>
    </Stack>
  );
}
