import * as React from "react";
import { styled, useTheme, alpha } from "@mui/material/styles";
import useMediaQuery from "@mui/material/useMediaQuery";
import Box from "@mui/material/Box";
import MuiAppBar from "@mui/material/AppBar";
import Toolbar from "@mui/material/Toolbar";
import Typography from "@mui/material/Typography";
import IconButton from "@mui/material/IconButton";
import MenuIcon from "@mui/icons-material/Menu";
import Checkbox from "@mui/material/Checkbox";
import FormGroup from "@mui/material/FormGroup";
import { Stack } from "@mui/material";
import { IoPersonOutline } from "react-icons/io5";
import { MdOutlineDarkMode, MdOutlineLightMode } from "react-icons/md";
import { IoIosNotificationsOutline } from "react-icons/io";
import { IoSettingsOutline } from "react-icons/io5";

const drawerWidth = 240;

const checklistItems = [
  "Single family home?",
  "Owner of address?",
  "Decision maker?",
  "Name?",
  "phone number?"
];

const AppBar = styled(MuiAppBar, {
  shouldForwardProp: (prop) => prop !== "open" && prop !== "mobile",
})(({ theme }) => ({
  zIndex: theme.zIndex.drawer + 1,
  transition: theme.transitions.create(["width", "margin"], {
    easing: theme.transitions.easing.sharp,
    duration: theme.transitions.duration.leavingScreen,
  }),
  variants: [
    {
      props: ({ open, mobile }) => open && !mobile,
      style: {
        marginLeft: drawerWidth,
        width: `calc(100% - ${drawerWidth}px)`,
        transition: theme.transitions.create(["width", "margin"], {
          easing: theme.transitions.easing.sharp,
          duration: theme.transitions.duration.enteringScreen,
        }),
      },
    },
  ],
}));

const TopBar = React.memo(({ handleDrawerOpen, open, mobile, setMode }) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const [checked, setChecked] = React.useState(
    checklistItems.reduce((acc, item) => ({ ...acc, [item]: false }), {})
  );

  const toggleChecked = React.useCallback((item) => {
    setChecked((prev) => ({ ...prev, [item]: !prev[item] }));
  }, []);

  return (
    <AppBar position="fixed" open={open} mobile={isMobile}>
      <Toolbar sx={{ flexWrap: "nowrap", gap: 1, alignItems: "center", height: 64, minHeight: 64, maxHeight: 64, overflowX: "auto", overflowY: "hidden", position: "relative" }}>
        <IconButton
          color="inherit"
          aria-label="open drawer"
          onClick={handleDrawerOpen}
          edge="start"
          sx={[
            {
              marginRight: 5,
            },
            open && !mobile && { display: "none" },
          ]}
        >
          <MenuIcon />
        </IconButton>
        

        <Stack direction={"row"} sx={{ position: "absolute", right: 0 }}>
          {theme.palette.mode === "light" ? (
            <IconButton
              color="inherit"
              aria-label="delete"
              onClick={() => {
                localStorage.setItem(
                  "CurrentMode",
                  theme.palette.mode === "light" ? "dark" : "light"
                );
                setMode((prevMode) =>
                  prevMode === "light" ? "dark" : "light"
                );
              }}
            >
              <MdOutlineDarkMode />
            </IconButton>
          ) : (
            <IconButton
              color="inherit"
              aria-label="delete"
              onClick={() => {
                localStorage.setItem(
                  "CurrentMode",
                  theme.palette.mode === "light" ? "dark" : "light"
                );
                setMode((prevMode) =>
                  prevMode === "light" ? "dark" : "light"
                );
              }}
            >
              <MdOutlineLightMode />
            </IconButton>
          )}

          <IconButton color="inherit" aria-label="delete">
            <IoIosNotificationsOutline />
          </IconButton>
          <IconButton color="inherit" aria-label="delete">
            <IoSettingsOutline />
          </IconButton>
          <IconButton color="inherit" aria-label="delete">
            <IoPersonOutline />
          </IconButton>
        </Stack>
      </Toolbar>
    </AppBar>
  );
});

export default TopBar;
