import React from "react";
import { useForm } from "react-hook-form";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import { Button } from "@mui/material";
import Snackbar from "@mui/material/Snackbar";
import Alert from "@mui/material/Alert";

const regExp =
  /^(([^<>()\[\]\\.,;:\s@"]+(\.[^<>()\[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;

const regPassword =
  /^(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9])(?=.*[!@#\$%\^&\*])(?=.{8,})/;
const data = [
  {
    value: "User",
    label: "User",
  },
  {
    value: "Manager",
    label: "Manager",
  },
  {
    value: "Admin",
    label: "Admin",
  },
];

export default function Profile() {
  const [open, setOpen] = React.useState(false);

  const handleClick = () => {
    setOpen(true);
  };

  const handleClose = (event, reason) => {
    if (reason === "clickaway") {
      return;
    }

    setOpen(false);
  };

  const {
    handleSubmit,
    register,
    formState: { errors },
  } = useForm();
  const onSubmit = () => {
    handleClick();
  };

  return (
    <Box
      onSubmit={handleSubmit(onSubmit)}
      component="form"
      sx={{ display: "flex", flexDirection: "column", gap: 2 }}
      noValidate
      autoComplete="off"
    >
      <Box sx={{ display: "flex", flexDirection: "row", gap: 2 }}>
        {" "}
        <TextField
          error={Boolean(errors.firstName)}
          helperText={
            Boolean(errors.firstName)
              ? "This field is required & min 3 character"
              : null
          }
          sx={{ flex: 1 }}
          label="First Name"
          variant="filled"
          {...register("firstName", {
            required: true,
            minLength: 3,
          })}
        />
        <TextField
          sx={{ flex: 1 }}
          label="Last Name"
          variant="filled"
          error={Boolean(errors.lastName)}
          helperText={
            Boolean(errors.lastName)
              ? "This field is required & min 3 character"
              : null
          }
          {...register("lastName", { required: true, minLength: 3 })}
        />
      </Box>
      <TextField
        label="Email"
        variant="filled"
        error={Boolean(errors.Email)}
        helperText={
          Boolean(errors.Email) ? "Please provide a valid email address" : null
        }
        {...register("Email", {
          required: true,
          minLength: 3,
          pattern: regExp,
        })}
      />
      <TextField
        error={Boolean(errors.Contact)}
        helperText={
          Boolean(errors.Contact) ? "Please add your phone number" : null
        }
        {...register("Contact", {
          required: true,
          minLength: 5,
          pattern: /^[0-9]+$/,
        })}
        label="Contact"
        variant="filled"
        inputProps={{
          inputMode: "numeric", // This helps on mobile to bring up the numeric keyboard
          pattern: "[0-9]*", // Enforces numeric input in modern browsers
        }}
        onInput={(e) => {
          // Prevent anything except numbers
          e.target.value = e.target.value.replace(/[^0-9]/g, ""); // Only allows numbers
        }}
      />
      <TextField label="Address 1" variant="filled" />
      <TextField label="Address 2" variant="filled" />
      <TextField
        id="standard-select-currency-native"
        select
        label="Role"
        defaultValue="User"
        slotProps={{
          select: {
            native: true,
          },
        }}
        helperText="Please select your role"
        variant="filled"
      >
        {data.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </TextField>
      <Box sx={{ textAlign: "right" }}>
        <Button
          sx={{ textTransform: "capitalize" }}
          type="submit"
          variant="contained"
        >
          Create New User
        </Button>
        <Snackbar
          anchorOrigin={{ vertical: "top", horizontal: "right" }}
          open={open}
          autoHideDuration={3000}
          onClose={handleClose}
        >
          <Alert
            onClose={handleClose}
            severity="info"
            variant="filled"
            sx={{ width: "100%" }}
          >
            Account created successfully.
          </Alert>
        </Snackbar>
      </Box>
    </Box>
  );
}
